/**
 * Função de Orquestração / Observer Automático:
 * Varre as reservas de um usuário e sincroniza novos selos para partidas concluídas.
 * Se atingir o teto de 12 horas, gera o Voucher automaticamente sem atrito humano.
 *
 * @param usuarioId ID do usuário
 * @param reservasDoUsuario Lista de reservas pertencentes ao usuário
 * @param campanha Campanha ativa
 * @returns Selos atualizados e voucher gerado, se houver
 */
export async function sincronizarFidelidadeAutomatica(
  usuarioId: string,
  reservasDoUsuario: Reserva[],
  campanha: CampanhaFidelidade
): Promise<{
  novosSelosGerados: SeloFidelidade[];
  voucherGerado: VoucherFidelidade | null;
}> {
  if (!usuarioId || !campanha.ativo) {
    return { novosSelosGerados: [], voucherGerado: null };
  }

  // 1. Carrega selos e vouchers já existentes
  const selosAtuais = await fetchSelosUsuarioSupabase(usuarioId);
  const vouchersAtuais = await fetchVouchersUsuarioSupabase(usuarioId);

  // 2. Avalia reservas elegíveis que ainda não ganharam selos
  const novosSelos: SeloFidelidade[] = [];
  const momentoAgora = new Date();

  for (const reserva of reservasDoUsuario) {
    const avaliacao = avaliarElegibilidadeReservaParaSelo(
      reserva,
      [...selosAtuais, ...novosSelos],
      momentoAgora
    );

    if (avaliacao.elegivel) {
      const selo = construirSeloParaReserva(reserva, usuarioId, campanha);
      novosSelos.push(selo);
      await inserirSeloSupabase(selo);
    }
  }

  const todosSelosAcumulados = [...selosAtuais, ...novosSelos];

  // 3. Avalia se atingiu a meta para gerar o voucher automático
  const progresso = calcularProgressoUsuario(
    usuarioId,
    todosSelosAcumulados,
    vouchersAtuais,
    campanha
  );

  let voucherGerado: VoucherFidelidade | null = null;

  if (progresso.podeResgatar) {
    try {
      const resgate = resgatarVoucherFidelidade(
        usuarioId,
        progresso.selosAtivos,
        campanha
      );

      await atualizarSelosSupabase(resgate.selosUtilizados);
      voucherGerado = await criarVoucherSupabase(resgate.voucher);
    } catch (err) {
      console.error("[FidelidadeService] Erro ao consolidar voucher automático:", err);
    }
  }

  return {
    novosSelosGerados: novosSelos,
    voucherGerado,
  };
}

/**
 * Hook customizado de abstração para o Sistema de Fidelidade.
 * Conecta os componentes de interface às regras de negócio, dados de reservas
 * e à camada de persistência com Supabase e LocalStorage.
 */

"use client";

import { useState, useEffect, useCallback, useMemo } from "react";
import { useUserAuth } from "@/hooks/useUserAuth";
import { useReservasService } from "@/hooks/useReservasService";
import type {
  CampanhaFidelidade,
  SeloFidelidade,
  VoucherFidelidade,
  ProgressoFidelidadeUsuario,
} from "@/lib/fidelidade/types";
import {
  CAMPANHA_PADRAO,
  calcularProgressoUsuario,
  resgatarVoucherFidelidade,
} from "@/lib/fidelidade/fidelidadeService";
import {
  fetchCampanhaSupabase,
  salvarCampanhaSupabase,
  fetchSelosUsuarioSupabase,
  fetchVouchersUsuarioSupabase,
  atualizarSelosSupabase,
  criarVoucherSupabase,
  marcarVoucherUtilizadoSupabase,
  sincronizarFidelidadeAutomatica,
} from "@/lib/supabase/fidelidadeService";

export function useFidelidadeService() {
  const { user } = useUserAuth();
  const { reservas } = useReservasService();

  const [campanha, setCampanha] = useState<CampanhaFidelidade>(CAMPANHA_PADRAO);
  const [selos, setSelos] = useState<SeloFidelidade[]>([]);
  const [vouchers, setVouchers] = useState<VoucherFidelidade[]>([]);
  const [carregando, setCarregando] = useState<boolean>(true);
  const [ultimoVoucherEmitido, setUltimoVoucherEmitido] = useState<VoucherFidelidade | null>(null);

  const usuarioId = user?.id || "";

  // ── Carregamento e Sincronização ──────────────────────────────────────────

  const recarregarDados = useCallback(async () => {
    try {
      setCarregando(true);
      const camp = await fetchCampanhaSupabase();
      setCampanha(camp);

      if (usuarioId) {
        // Filtra reservas do usuário atual (por userId ou por telefone cadastrado)
        const reservasDoUsuario = reservas.filter(
          (r) =>
            r.userId === usuarioId ||
            (user?.telefone && r.whatsappCliente && r.whatsappCliente.includes(user.telefone.replace(/\D/g, "")))
        );

        // Dispara o observer de sincronização automática para reservas recém-concluídas
        const { voucherGerado } = await sincronizarFidelidadeAutomatica(
          usuarioId,
          reservasDoUsuario,
          camp
        );

        if (voucherGerado) {
          setUltimoVoucherEmitido(voucherGerado);
        }

        const [selosDb, vouchersDb] = await Promise.all([
          fetchSelosUsuarioSupabase(usuarioId),
          fetchVouchersUsuarioSupabase(usuarioId),
        ]);

        setSelos(selosDb);
        setVouchers(vouchersDb);
      }
    } catch (err) {
      console.error("[useFidelidadeService] Falha ao sincronizar fidelidade:", err);
    } finally {
      setCarregando(false);
    }
  }, [usuarioId, user?.telefone, reservas]);

  useEffect(() => {
    void recarregarDados();
  }, [recarregarDados]);

  // ── Progresso Computado Reativamente ───────────────────────────────────────

  const progresso: ProgressoFidelidadeUsuario = useMemo(() => {
    if (!usuarioId) {
      return calcularProgressoUsuario("", [], [], campanha);
    }
    return calcularProgressoUsuario(usuarioId, selos, vouchers, campanha);
  }, [usuarioId, selos, vouchers, campanha]);

  // ── Ações do Cliente ──────────────────────────────────────────────────────

  /**
   * Resgata manualmente o voucher caso o usuário tenha completado as horas.
   */
  const resgatarVoucher = useCallback(async (): Promise<{
    sucesso: boolean;
    voucher?: VoucherFidelidade;
    erro?: string;
  }> => {
    if (!usuarioId) {
      return { sucesso: false, erro: "Usuário precisa estar autenticado." };
    }

    if (!progresso.podeResgatar) {
      return {
        sucesso: false,
        erro: `Você precisa acumular ${campanha.horasNecessarias} horas para gerar um voucher.`,
      };
    }

    try {
      const resgate = resgatarVoucherFidelidade(
        usuarioId,
        progresso.selosAtivos,
        campanha
      );

      await atualizarSelosSupabase(resgate.selosUtilizados);
      const voucherCriado = await criarVoucherSupabase(resgate.voucher);

      setUltimoVoucherEmitido(voucherCriado);
      await recarregarDados();

      return { sucesso: true, voucher: voucherCriado };
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Erro desconhecido ao resgatar voucher.";
      return { sucesso: false, erro: msg };
    }
  }, [usuarioId, progresso, campanha, recarregarDados]);

  /**
   * Marca um voucher como utilizado no checkout de uma nova reserva.
   */
  const consumirVoucherNoCheckout = useCallback(
    async (voucherId: string, reservaId: string): Promise<boolean> => {
      try {
        const ok = await marcarVoucherUtilizadoSupabase(voucherId, reservaId);
        if (ok) {
          await recarregarDados();
        }
        return ok;
      } catch (err) {
        console.error("[useFidelidadeService] Erro ao consumir voucher:", err);
        return false;
      }
    },
    [recarregarDados]
  );

  // ── Ações do Administrador ────────────────────────────────────────────────

  /**
   * Atualiza a configuração global da campanha de fidelidade da arena.
   */
  const atualizarCampanha = useCallback(
    async (dadosNovos: Partial<CampanhaFidelidade>): Promise<boolean> => {
      try {
        const nova = {
          ...campanha,
          ...dadosNovos,
          atualizadoEm: new Date().toISOString(),
        };
        const salva = await salvarCampanhaSupabase(nova);
        setCampanha(salva);
        return true;
      } catch (err) {
        console.error("[useFidelidadeService] Erro ao atualizar campanha:", err);
        return false;
      }
    },
    [campanha]
  );

  return {
    campanha,
    selos,
    vouchers,
    progresso,
    carregando,
    ultimoVoucherEmitido,
    setUltimoVoucherEmitido,
    recarregarDados,
    resgatarVoucher,
    consumirVoucherNoCheckout,
    atualizarCampanha,
  };
}

/**
 * Componente Visual da Cartela de Fidelidade e Timeline com Selos/Checks.
 * Permite ao cliente acompanhar suas horas jogadas, validade dos selos,
 * ticket médio acumulado e vouchers de desconto disponíveis.
 */

"use client";

import { useState } from "react";
import Link from "next/link";
import {
  Award,
  Gift,
  CheckCircle2,
  Clock,
  Sparkles,
  AlertTriangle,
  Copy,
  Check,
  Calendar,
  Ticket,
  ChevronRight,
  TrendingUp,
} from "lucide-react";
import { formatarMoeda, formatarDataExibicao } from "@/lib/constants";
import type { ProgressoFidelidadeUsuario, VoucherFidelidade } from "@/lib/fidelidade/types";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

interface Props {
  progresso: ProgressoFidelidadeUsuario;
  carregando: boolean;
  onResgatarVoucher?: () => Promise<{ sucesso: boolean; voucher?: VoucherFidelidade; erro?: string }>;
}

export function CartelaFidelidadeTimeline({
  progresso,
  carregando,
  onResgatarVoucher,
}: Props) {
  const [copiadoId, setCopiadoId] = useState<string | null>(null);
  const [resgatando, setResgatando] = useState(false);

  const handleCopiarCodigo = (codigo: string, id: string) => {
    void navigator.clipboard.writeText(codigo);
    setCopiadoId(id);
    toast.success("Código do voucher copiado!");
    setTimeout(() => setCopiadoId(null), 2500);
  };

  const handleResgate = async () => {
    if (!onResgatarVoucher) return;
    setResgatando(true);
    try {
      const res = await onResgatarVoucher();
      if (res.sucesso && res.voucher) {
        toast.success(`🎉 Parabéns! Voucher ${res.voucher.codigo} gerado com sucesso!`);
      } else if (res.erro) {
        toast.error(res.erro);
      }
    } catch {
      toast.error("Falha ao resgatar voucher.");
    } finally {
      setResgatando(false);
    }
  };

  if (carregando) {
    return (
      <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-8 flex flex-col items-center justify-center min-h-[300px]">
        <div className="w-8 h-8 border-2 border-emerald-400 border-t-transparent rounded-full animate-spin mb-4" />
        <p className="text-slate-400 text-sm">Carregando seu cartão de fidelidade...</p>
      </div>
    );
  }

  const metaHoras = progresso.horasNecessarias || 12;
  const horasCompletadas = Math.min(progresso.totalHorasAtivas, metaHoras);
  const faltamHoras = Math.max(0, metaHoras - progresso.totalHorasAtivas);

  return (
    <div className="space-y-6">
      {/* ── Card Principal da Cartela ────────────────────────────────────────── */}
      <div className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-slate-900 via-slate-900 to-slate-950 border border-slate-800/80 p-6 sm:p-8 shadow-2xl">
        {/* Glow decorativo de fundo */}
        <div className="absolute top-0 right-0 w-96 h-96 bg-emerald-500/10 rounded-full blur-3xl pointer-events-none -mr-20 -mt-20" />
        <div className="absolute bottom-0 left-0 w-80 h-80 bg-amber-500/5 rounded-full blur-3xl pointer-events-none -ml-20 -mb-20" />

        <div className="relative z-10">
          {/* Header com Título e Badges */}
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-6 border-b border-slate-800/80">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center flex-shrink-0 shadow-inner">
                <Gift className="w-6 h-6 text-emerald-400" />
              </div>
              <div>
                <div className="flex items-center gap-2">
                  <h2 className="text-lg sm:text-xl font-bold text-white tracking-tight">
                    Cartela de Fidelidade
                  </h2>
                  <span className="px-2.5 py-0.5 rounded-full text-[11px] font-semibold bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                    Ativa
                  </span>
                </div>
                <p className="text-xs text-slate-400 mt-1">
                  Complete {metaHoras} horas de jogo avulso em até 3 meses para ganhar 1 voucher!
                </p>
              </div>
            </div>

            {/* Ticket Médio Acumulado */}
            <div className="flex items-center gap-3 bg-slate-800/60 border border-slate-700/60 rounded-2xl px-4 py-2.5 backdrop-blur-sm self-start sm:self-auto">
              <TrendingUp className="w-4 h-4 text-emerald-400" />
              <div>
                <p className="text-[10px] uppercase font-bold text-slate-400 tracking-wider">
                  Ticket Médio Atual
                </p>
                <p className="text-sm font-black text-emerald-300">
                  {progresso.ticketMedioAtual > 0
                    ? `${formatarMoeda(progresso.ticketMedioAtual)} / hora`
                    : "R$ 0,00"}
                </p>
              </div>
            </div>
          </div>

          {/* Barra de Progresso Quantitativa */}
          <div className="my-6">
            <div className="flex justify-between items-end mb-2">
              <div>
                <span className="text-2xl font-black text-white">{horasCompletadas}</span>
                <span className="text-slate-400 text-sm font-semibold"> / {metaHoras} horas</span>
              </div>
              <span className="text-xs font-bold text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded-md">
                {progresso.percentualConcluido}% concluído
              </span>
            </div>

            <div className="w-full h-3 rounded-full bg-slate-800 overflow-hidden p-0.5 border border-slate-700/50">
              <div
                className="h-full rounded-full bg-gradient-to-r from-emerald-500 via-teal-400 to-emerald-300 transition-all duration-700 ease-out shadow-sm"
                style={{ width: `${progresso.percentualConcluido}%` }}
              />
            </div>
          </div>

          {/* ── Timeline com os 12 Checks / Selos ────────────────────────────── */}
          <div className="py-4">
            <p className="text-xs font-bold uppercase tracking-wider text-slate-400 mb-4 flex items-center gap-2">
              <Clock className="w-3.5 h-3.5 text-slate-400" />
              Timeline de Carimbos ({horasCompletadas} de {metaHoras})
            </p>

            <div className="grid grid-cols-4 sm:grid-cols-6 lg:grid-cols-12 gap-2.5">
              {Array.from({ length: metaHoras }).map((_, index) => {
                const horaNumero = index + 1;
                const estaPreenchido = horaNumero <= progresso.totalHorasAtivas;
                const ehUltimo = horaNumero === metaHoras;

                // Encontra qual selo cobriu esta hora
                let seloCorrespondente = null;
                let acumulador = 0;
                for (const s of progresso.selosAtivos) {
                  acumulador += s.horasContabilizadas || 1;
                  if (acumulador >= horaNumero) {
                    seloCorrespondente = s;
                    break;
                  }
                }

                return (
                  <div
                    key={horaNumero}
                    className={`relative flex flex-col items-center justify-center p-2.5 rounded-2xl border transition-all duration-200 group
                      ${
                        estaPreenchido
                          ? "bg-emerald-500/15 border-emerald-500/40 text-emerald-300 shadow-md shadow-emerald-950/40"
                          : "bg-slate-800/40 border-slate-700/50 text-slate-500"
                      }
                      ${ehUltimo && !estaPreenchido ? "border-amber-500/30 bg-amber-500/5" : ""}
                    `}
                  >
                    {/* Ícone */}
                    <div className="w-8 h-8 rounded-xl flex items-center justify-center mb-1 transition-transform group-hover:scale-110">
                      {estaPreenchido ? (
                        <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                      ) : ehUltimo ? (
                        <Award className="w-5 h-5 text-amber-400 animate-pulse" />
                      ) : (
                        <span className="text-xs font-bold text-slate-500">{horaNumero}h</span>
                      )}
                    </div>

                    <span className="text-[10px] font-semibold">
                      {ehUltimo ? "Prêmio 🎁" : `${horaNumero}ª h`}
                    </span>

                    {/* Tooltip com info do selo ao passar mouse */}
                    {seloCorrespondente && (
                      <div className="absolute bottom-full mb-2 hidden group-hover:block z-30 bg-slate-950 border border-slate-700 text-slate-200 text-[10px] rounded-lg p-2 shadow-xl whitespace-nowrap pointer-events-none">
                        <p className="font-bold text-emerald-400">
                          Jogo em {formatarDataExibicao(seloCorrespondente.dataJogo)}
                        </p>
                        <p>Valor: {formatarMoeda(seloCorrespondente.valorPorHora)}/h</p>
                        <p className="text-slate-400">
                          Expira em {formatarDataExibicao(seloCorrespondente.expiraEm)}
                        </p>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Aviso de Expiração / Urgência */}
          {progresso.diasParaProximoSeloExpirar !== null && (
            <div className="mt-4 flex items-center gap-3 bg-amber-500/10 border border-amber-500/20 rounded-2xl p-3.5 text-xs text-amber-300">
              <AlertTriangle className="w-4 h-4 text-amber-400 flex-shrink-0" />
              <div className="flex-1">
                <span className="font-semibold">Fique atento à validade: </span>
                Seu selo mais antigo expira em{" "}
                <strong className="underline">
                  {progresso.diasParaProximoSeloExpirar} dia(s)
                </strong>{" "}
                ({formatarDataExibicao(progresso.proximoSeloExpirandoEm || "")}). Complete suas horas
                restantes para não perder seu progresso!
              </div>
            </div>
          )}

          {/* Botão de Resgate Manual se elegível */}
          {progresso.podeResgatar && (
            <div className="mt-6 pt-6 border-t border-slate-800 flex flex-col sm:flex-row items-center justify-between gap-4">
              <div className="flex items-center gap-2">
                <Sparkles className="w-5 h-5 text-amber-400 animate-bounce" />
                <p className="text-sm font-bold text-white">
                  Você completou as {metaHoras} horas! Seu voucher está pronto para ser gerado.
                </p>
              </div>

              <Button
                onClick={handleResgate}
                disabled={resgatando}
                className="w-full sm:w-auto bg-gradient-to-r from-emerald-500 to-teal-400 hover:from-emerald-400 hover:to-teal-300 text-slate-950 font-black px-6 h-11 rounded-xl shadow-lg shadow-emerald-500/25"
              >
                {resgatando ? "Gerando Voucher..." : "Resgatar Voucher Agora 🎁"}
              </Button>
            </div>
          )}

          {/* Mensagem motivacional de quantas horas faltam */}
          {!progresso.podeResgatar && faltamHoras > 0 && (
            <p className="text-xs text-slate-400 mt-4 text-center">
              Faltam apenas <strong className="text-emerald-400">{faltamHoras} hora(s)</strong> de
              jogo concluído para desbloquear seu desconto especial.
            </p>
          )}
        </div>
      </div>

      {/* ── Seção de Vouchers Disponíveis ───────────────────────────────────── */}
      {progresso.vouchersDisponiveis.length > 0 && (
        <div className="space-y-4">
          <div className="flex items-center gap-2">
            <Ticket className="w-5 h-5 text-emerald-400" />
            <h3 className="text-base font-bold text-white">
              Seus Vouchers Disponíveis ({progresso.vouchersDisponiveis.length})
            </h3>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {progresso.vouchersDisponiveis.map((voucher) => (
              <div
                key={voucher.id}
                className="relative overflow-hidden rounded-2xl bg-slate-900 border border-emerald-500/40 p-5 shadow-lg flex flex-col justify-between"
              >
                <div className="flex justify-between items-start gap-4">
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="px-2 py-0.5 rounded-full text-[10px] font-extrabold uppercase bg-emerald-500/20 text-emerald-300 border border-emerald-500/30">
                        Voucher de Fidelidade
                      </span>
                    </div>
                    <p className="text-2xl font-black text-white mt-2">
                      Até {formatarMoeda(voucher.valorTeto)}
                    </p>
                    <p className="text-xs text-slate-400 mt-0.5">
                      Abatimento no valor de uma nova reserva
                    </p>
                  </div>

                  <div className="w-10 h-10 rounded-xl bg-emerald-500/10 flex items-center justify-center">
                    <Gift className="w-5 h-5 text-emerald-400" />
                  </div>
                </div>

                <div className="mt-6 pt-4 border-t border-slate-800 flex flex-col sm:flex-row items-center justify-between gap-3">
                  <div className="w-full sm:w-auto flex items-center justify-between sm:justify-start gap-2 bg-slate-950 px-3 py-1.5 rounded-xl border border-slate-800">
                    <span className="text-xs font-mono font-bold text-emerald-300">
                      {voucher.codigo}
                    </span>
                    <button
                      onClick={() => handleCopiarCodigo(voucher.codigo, voucher.id)}
                      className="text-slate-400 hover:text-white p-1"
                      title="Copiar código"
                    >
                      {copiadoId === voucher.id ? (
                        <Check className="w-3.5 h-3.5 text-emerald-400" />
                      ) : (
                        <Copy className="w-3.5 h-3.5" />
                      )}
                    </button>
                  </div>

                  <div className="text-[11px] text-slate-500 flex items-center gap-1 self-start sm:self-auto">
                    <Calendar className="w-3 h-3" />
                    Válido até {formatarDataExibicao(voucher.expiraEm)}
                  </div>
                </div>

                <div className="mt-3">
                  <Link href="/" className="w-full block">
                    <Button
                      variant="outline"
                      className="w-full border-emerald-500/30 hover:bg-emerald-500/10 text-emerald-300 font-bold text-xs h-9 rounded-xl flex items-center justify-center gap-1"
                    >
                      Usar no Agendamento
                      <ChevronRight className="w-3.5 h-3.5" />
                    </Button>
                  </Link>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ── Histórico de Vouchers Usados / Expirados ────────────────────────── */}
      {progresso.vouchersHistorico.length > 0 && (
        <div className="space-y-3 pt-4">
          <h4 className="text-xs font-bold uppercase tracking-wider text-slate-500">
            Histórico de Vouchers Anteriores
          </h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
            {progresso.vouchersHistorico.map((v) => (
              <div
                key={v.id}
                className="bg-slate-900/40 border border-slate-800 rounded-xl p-3.5 text-xs flex justify-between items-center opacity-70"
              >
                <div>
                  <p className="font-mono font-bold text-slate-300">{v.codigo}</p>
                  <p className="text-slate-500 text-[10px]">Teto: {formatarMoeda(v.valorTeto)}</p>
                </div>
                <span
                  className={`px-2 py-0.5 rounded text-[10px] font-semibold ${
                    v.status === "utilizado"
                      ? "bg-slate-800 text-slate-400"
                      : "bg-red-500/10 text-red-400"
                  }`}
                >
                  {v.status === "utilizado" ? "Utilizado" : "Expirado"}
                </span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * Painel Administrativo de Gerenciamento do Programa de Fidelidade.
 * Permite ao gestor da arena configurar parâmetros da campanha (horas necessárias,
 * validade em meses, prazo do voucher), acompanhar métricas de retenção (LTV)
 * e inspecionar todos os vouchers e selos emitidos no sistema.
 */

"use client";

import { useState, useEffect, useMemo } from "react";
import { toast } from "sonner";
import {
  Gift,
  Save,
  TrendingUp,
  Ticket,
  CheckCircle2,
  Clock,
  Users,
  Search,
  Filter,
  RefreshCw,
  AlertCircle,
  Calendar,
  Sparkles,
} from "lucide-react";
import { formatarMoeda, formatarDataExibicao } from "@/lib/constants";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useFidelidadeService } from "@/hooks/useFidelidadeService";
import {
  fetchTodosVouchersAdminSupabase,
  fetchTodosSelosAdminSupabase,
} from "@/lib/supabase/fidelidadeService";
import type { VoucherFidelidade, SeloFidelidade } from "@/lib/fidelidade/types";

export function AdminFidelidadePage() {
  const { campanha, atualizarCampanha, carregando } = useFidelidadeService();

  // Estados locais para edição das configurações
  const [nomeCampanha, setNomeCampanha] = useState("");
  const [horasNecessarias, setHorasNecessarias] = useState<number>(12);
  const [mesesValidade, setMesesValidade] = useState<number>(3);
  const [diasValidadeVoucher, setDiasValidadeVoucher] = useState<number>(60);
  const [ativo, setAtivo] = useState<boolean>(true);
  const [salvandoConfig, setSalvandoConfig] = useState(false);

  // Estados de listagens globais
  const [todosVouchers, setTodosVouchers] = useState<VoucherFidelidade[]>([]);
  const [todosSelos, setTodosSelos] = useState<SeloFidelidade[]>([]);
  const [carregandoListas, setCarregandoListas] = useState(true);

  // Filtros
  const [buscaVoucher, setBuscaVoucher] = useState("");
  const [filtroStatusVoucher, setFiltroStatusVoucher] = useState<string>("todos");
  const [abaAtual, setAbaAtual] = useState<"configuracao" | "vouchers" | "metricas">("metricas");

  // Inicializa dados do formulário quando campanha carrega
  useEffect(() => {
    if (campanha) {
      setNomeCampanha(campanha.nome);
      setHorasNecessarias(campanha.horasNecessarias);
      setMesesValidade(campanha.mesesValidade);
      setDiasValidadeVoucher(campanha.diasValidadeVoucher);
      setAtivo(campanha.ativo);
    }
  }, [campanha]);

  // Carrega todos os vouchers e selos do sistema
  const carregarDadosGlobais = async () => {
    setCarregandoListas(true);
    try {
      const [vouchersData, selosData] = await Promise.all([
        fetchTodosVouchersAdminSupabase(),
        fetchTodosSelosAdminSupabase(),
      ]);
      setTodosVouchers(vouchersData);
      setTodosSelos(selosData);
    } catch (err) {
      console.error("[AdminFidelidadePage] Erro ao carregar dados administrativos:", err);
      toast.error("Erro ao carregar dados do programa.");
    } finally {
      setCarregandoListas(false);
    }
  };

  useEffect(() => {
    void carregarDadosGlobais();
  }, []);

  // ── Salvar Configurações ──────────────────────────────────────────────────

  const handleSalvarConfig = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!nomeCampanha.trim()) {
      toast.error("O nome da campanha é obrigatório.");
      return;
    }

    if (horasNecessarias < 1 || horasNecessarias > 100) {
      toast.error("A meta de horas deve estar entre 1 e 100.");
      return;
    }

    if (mesesValidade < 1 || mesesValidade > 12) {
      toast.error("A validade em meses deve estar entre 1 e 12 meses.");
      return;
    }

    if (diasValidadeVoucher < 5 || diasValidadeVoucher > 365) {
      toast.error("A validade do voucher deve estar entre 5 e 365 dias.");
      return;
    }

    setSalvandoConfig(true);
    try {
      const ok = await atualizarCampanha({
        nome: nomeCampanha.trim(),
        horasNecessarias,
        mesesValidade,
        diasValidadeVoucher,
        ativo,
      });

      if (ok) {
        toast.success("Configurações do programa de fidelidade salvas com sucesso!");
      } else {
        toast.error("Erro ao salvar configurações.");
      }
    } finally {
      setSalvandoConfig(false);
    }
  };

  // ── Métricas Computadas ───────────────────────────────────────────────────

  const metricas = useMemo(() => {
    const totalVouchersEmitidos = todosVouchers.length;
    const vouchersUtilizados = todosVouchers.filter((v) => v.status === "utilizado");
    const vouchersDisponiveis = todosVouchers.filter((v) => v.status === "disponivel");
    const vouchersExpirados = todosVouchers.filter((v) => v.status === "expirado");

    const totalHorasAcumuladas = todosSelos.reduce(
      (acc, s) => acc + (s.horasContabilizadas || 1),
      0
    );

    const valorTotalDescontosConcedidos = vouchersUtilizados.reduce(
      (acc, v) => acc + (Number(v.valorTeto) || 0),
      0
    );

    const taxaResgate =
      totalVouchersEmitidos > 0
        ? Math.round((vouchersUtilizados.length / totalVouchersEmitidos) * 100)
        : 0;

    // Clientes únicos participantes
    const usuariosUnicos = new Set(todosSelos.map((s) => s.usuarioId)).size;

    return {
      totalVouchersEmitidos,
      vouchersUtilizados: vouchersUtilizados.length,
      vouchersDisponiveis: vouchersDisponiveis.length,
      vouchersExpirados: vouchersExpirados.length,
      totalHorasAcumuladas,
      valorTotalDescontosConcedidos,
      taxaResgate,
      usuariosUnicos,
    };
  }, [todosVouchers, todosSelos]);

  // Vouchers filtrados para tabela
  const vouchersFiltrados = useMemo(() => {
    return todosVouchers.filter((v) => {
      const matchBusca =
        !buscaVoucher ||
        v.codigo.toLowerCase().includes(buscaVoucher.toLowerCase()) ||
        v.usuarioId.toLowerCase().includes(buscaVoucher.toLowerCase());

      const matchStatus =
        filtroStatusVoucher === "todos" || v.status === filtroStatusVoucher;

      return matchBusca && matchStatus;
    });
  }, [todosVouchers, buscaVoucher, filtroStatusVoucher]);

  return (
    <div className="space-y-6">
      {/* ── Header ───────────────────────────────────────────────────────────── */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center">
              <Gift className="w-5 h-5 text-emerald-400" />
            </div>
            <div>
              <h1 className="text-xl sm:text-2xl font-bold text-white tracking-tight">
                Programa de Fidelidade
              </h1>
              <p className="text-xs sm:text-sm text-slate-400">
                Gerencie regras de retenção, ticket médio e vouchers promocionais.
              </p>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={carregarDadosGlobais}
            disabled={carregandoListas}
            className="border-slate-700 text-slate-300 hover:text-white hover:bg-slate-800 text-xs gap-1.5"
          >
            <RefreshCw className={`w-3.5 h-3.5 ${carregandoListas ? "animate-spin" : ""}`} />
            Atualizar Dados
          </Button>
        </div>
      </div>

      {/* ── Cards de Métricas Principais ─────────────────────────────────────── */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-5">
          <div className="flex items-center justify-between mb-2">
            <span className="text-xs font-medium text-slate-400">Horas Acumuladas</span>
            <Clock className="w-4 h-4 text-emerald-400" />
          </div>
          <p className="text-2xl font-black text-white">{metricas.totalHorasAcumuladas}h</p>
          <p className="text-[11px] text-slate-500 mt-1">
            {metricas.usuariosUnicos} jogador(es) ativos na cartela
          </p>
        </div>

        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-5">
          <div className="flex items-center justify-between mb-2">
            <span className="text-xs font-medium text-slate-400">Vouchers Emitidos</span>
            <Ticket className="w-4 h-4 text-teal-400" />
          </div>
          <p className="text-2xl font-black text-white">{metricas.totalVouchersEmitidos}</p>
          <p className="text-[11px] text-teal-400 mt-1">
            {metricas.vouchersDisponiveis} pronto(s) para uso
          </p>
        </div>

        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-5">
          <div className="flex items-center justify-between mb-2">
            <span className="text-xs font-medium text-slate-400">Taxa de Resgate</span>
            <TrendingUp className="w-4 h-4 text-amber-400" />
          </div>
          <p className="text-2xl font-black text-white">{metricas.taxaResgate}%</p>
          <p className="text-[11px] text-slate-500 mt-1">
            {metricas.vouchersUtilizados} voucher(s) utilizados
          </p>
        </div>

        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-5">
          <div className="flex items-center justify-between mb-2">
            <span className="text-xs font-medium text-slate-400">Descontos Aplicados</span>
            <Sparkles className="w-4 h-4 text-purple-400" />
          </div>
          <p className="text-2xl font-black text-white">
            {formatarMoeda(metricas.valorTotalDescontosConcedidos)}
          </p>
          <p className="text-[11px] text-slate-500 mt-1">Recompensa convertida em jogos</p>
        </div>
      </div>

      {/* ── Navegação por Abas ──────────────────────────────────────────────── */}
      <div className="flex border-b border-slate-800 gap-6 text-sm font-semibold">
        <button
          onClick={() => setAbaAtual("metricas")}
          className={`pb-3 transition-colors border-b-2 flex items-center gap-2 ${
            abaAtual === "metricas"
              ? "border-emerald-400 text-emerald-400"
              : "border-transparent text-slate-400 hover:text-slate-200"
          }`}
        >
          <TrendingUp className="w-4 h-4" />
          Visão Geral & Selos
        </button>

        <button
          onClick={() => setAbaAtual("vouchers")}
          className={`pb-3 transition-colors border-b-2 flex items-center gap-2 ${
            abaAtual === "vouchers"
              ? "border-emerald-400 text-emerald-400"
              : "border-transparent text-slate-400 hover:text-slate-200"
          }`}
        >
          <Ticket className="w-4 h-4" />
          Vouchers Emitidos ({todosVouchers.length})
        </button>

        <button
          onClick={() => setAbaAtual("configuracao")}
          className={`pb-3 transition-colors border-b-2 flex items-center gap-2 ${
            abaAtual === "configuracao"
              ? "border-emerald-400 text-emerald-400"
              : "border-transparent text-slate-400 hover:text-slate-200"
          }`}
        >
          <Save className="w-4 h-4" />
          Configuração da Campanha
        </button>
      </div>

      {/* ── Conteúdo da Aba: Configuração ───────────────────────────────────── */}
      {abaAtual === "configuracao" && (
        <div className="bg-slate-900/60 border border-slate-800 rounded-3xl p-6 sm:p-8 max-w-3xl">
          <div className="mb-6">
            <h3 className="text-base font-bold text-white">Regras da Campanha de Fidelidade</h3>
            <p className="text-xs text-slate-400 mt-1">
              Defina os parâmetros de horas, prazos de validade e comportamento da premiação.
            </p>
          </div>

          <form onSubmit={handleSalvarConfig} className="space-y-6">
            <div className="space-y-2">
              <Label htmlFor="nomeCampanha" className="text-xs font-bold text-slate-300">
                Nome da Campanha
              </Label>
              <Input
                id="nomeCampanha"
                value={nomeCampanha}
                onChange={(e) => setNomeCampanha(e.target.value)}
                placeholder="Ex: Fidelidade Campeão"
                className="bg-slate-950 border-slate-800 text-white"
                required
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div className="space-y-2">
                <Label htmlFor="horasNecessarias" className="text-xs font-bold text-slate-300">
                  Horas Necessárias (Meta)
                </Label>
                <div className="relative">
                  <Input
                    id="horasNecessarias"
                    type="number"
                    min="1"
                    max="100"
                    value={horasNecessarias}
                    onChange={(e) => setHorasNecessarias(Number(e.target.value))}
                    className="bg-slate-950 border-slate-800 text-white pr-8"
                    required
                  />
                  <span className="absolute right-3 top-2.5 text-xs text-slate-500 font-bold">h</span>
                </div>
                <p className="text-[11px] text-slate-500">Padrão alinhado: 12 horas</p>
              </div>

              <div className="space-y-2">
                <Label htmlFor="mesesValidade" className="text-xs font-bold text-slate-300">
                  Janela da Cartela
                </Label>
                <div className="relative">
                  <Input
                    id="mesesValidade"
                    type="number"
                    min="1"
                    max="12"
                    value={mesesValidade}
                    onChange={(e) => setMesesValidade(Number(e.target.value))}
                    className="bg-slate-950 border-slate-800 text-white pr-14"
                    required
                  />
                  <span className="absolute right-3 top-2.5 text-xs text-slate-500 font-bold">
                    meses
                  </span>
                </div>
                <p className="text-[11px] text-slate-500">Padrão alinhado: 3 meses</p>
              </div>

              <div className="space-y-2">
                <Label htmlFor="diasValidadeVoucher" className="text-xs font-bold text-slate-300">
                  Validade do Voucher
                </Label>
                <div className="relative">
                  <Input
                    id="diasValidadeVoucher"
                    type="number"
                    min="5"
                    max="365"
                    value={diasValidadeVoucher}
                    onChange={(e) => setDiasValidadeVoucher(Number(e.target.value))}
                    className="bg-slate-950 border-slate-800 text-white pr-12"
                    required
                  />
                  <span className="absolute right-3 top-2.5 text-xs text-slate-500 font-bold">
                    dias
                  </span>
                </div>
                <p className="text-[11px] text-slate-500">Prazo para utilizar o prêmio</p>
              </div>
            </div>

            {/* Switch Ativo / Inativo */}
            <div className="p-4 rounded-2xl bg-slate-950 border border-slate-800 flex items-center justify-between">
              <div>
                <p className="text-sm font-bold text-white">Programa de Fidelidade Ativo</p>
                <p className="text-xs text-slate-400 mt-0.5">
                  Quando ativo, novas reservas concluídas acumulam selos e geram vouchers
                  automaticamente.
                </p>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input
                  type="checkbox"
                  checked={ativo}
                  onChange={(e) => setAtivo(e.target.checked)}
                  className="sr-only peer"
                />
                <div className="w-11 h-6 bg-slate-800 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-emerald-500" />
              </label>
            </div>

            <div className="flex justify-end pt-4">
              <Button
                type="submit"
                disabled={salvandoConfig || carregando}
                className="bg-emerald-500 hover:bg-emerald-400 text-slate-950 font-bold px-6 h-11 rounded-xl gap-2 shadow-lg shadow-emerald-500/20"
              >
                <Save className="w-4 h-4" />
                {salvandoConfig ? "Salvando Alterações..." : "Salvar Configurações"}
              </Button>
            </div>
          </form>
        </div>
      )}

      {/* ── Conteúdo da Aba: Tabela de Vouchers ───────────────────────────────── */}
      {abaAtual === "vouchers" && (
        <div className="space-y-4">
          <div className="flex flex-col sm:flex-row gap-3 items-center justify-between">
            <div className="relative w-full sm:w-72">
              <Search className="w-4 h-4 text-slate-500 absolute left-3 top-3" />
              <Input
                placeholder="Buscar código ou usuário..."
                value={buscaVoucher}
                onChange={(e) => setBuscaVoucher(e.target.value)}
                className="pl-9 bg-slate-900 border-slate-800 text-xs text-white"
              />
            </div>

            <div className="flex items-center gap-2 self-start sm:self-auto">
              <Filter className="w-4 h-4 text-slate-500" />
              <select
                value={filtroStatusVoucher}
                onChange={(e) => setFiltroStatusVoucher(e.target.value)}
                className="bg-slate-900 border border-slate-800 text-slate-300 rounded-xl px-3 py-2 text-xs focus:outline-none"
              >
                <option value="todos">Todos os Status</option>
                <option value="disponivel">Disponível</option>
                <option value="utilizado">Utilizado</option>
                <option value="expirado">Expirado</option>
              </select>
            </div>
          </div>

          <div className="overflow-x-auto rounded-2xl border border-slate-800 bg-slate-900/60">
            <table className="w-full text-left text-xs text-slate-300">
              <thead className="bg-slate-950 text-slate-400 font-bold uppercase text-[10px] tracking-wider border-b border-slate-800">
                <tr>
                  <th className="py-3 px-4">Código Voucher</th>
                  <th className="py-3 px-4">Usuário</th>
                  <th className="py-3 px-4">Teto Desconto</th>
                  <th className="py-3 px-4">Status</th>
                  <th className="py-3 px-4">Criado Em</th>
                  <th className="py-3 px-4">Validade</th>
                  <th className="py-3 px-4">Reserva Usada</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800/60">
                {vouchersFiltrados.length === 0 ? (
                  <tr>
                    <td colSpan={7} className="py-8 text-center text-slate-500">
                      Nenhum voucher encontrado com os filtros selecionados.
                    </td>
                  </tr>
                ) : (
                  vouchersFiltrados.map((v) => (
                    <tr key={v.id} className="hover:bg-slate-800/30 transition-colors">
                      <td className="py-3.5 px-4 font-mono font-bold text-emerald-400">
                        {v.codigo}
                      </td>
                      <td className="py-3.5 px-4 text-slate-200">
                        <span className="truncate block max-w-[140px]" title={v.usuarioId}>
                          {v.usuarioId}
                        </span>
                      </td>
                      <td className="py-3.5 px-4 font-bold text-white">
                        {formatarMoeda(v.valorTeto)}
                      </td>
                      <td className="py-3.5 px-4">
                        <span
                          className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${
                            v.status === "disponivel"
                              ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20"
                              : v.status === "utilizado"
                              ? "bg-slate-800 text-slate-400"
                              : "bg-red-500/10 text-red-400 border border-red-500/20"
                          }`}
                        >
                          {v.status}
                        </span>
                      </td>
                      <td className="py-3.5 px-4 text-slate-400">
                        {formatarDataExibicao(v.criadoEm.split("T")[0])}
                      </td>
                      <td className="py-3.5 px-4 text-slate-400">
                        {formatarDataExibicao(v.expiraEm)}
                      </td>
                      <td className="py-3.5 px-4 text-slate-400">
                        {v.reservaUtilizadaId ? (
                          <span className="font-mono text-[11px] text-teal-300">
                            #{v.reservaUtilizadaId.substring(0, 8)}
                          </span>
                        ) : (
                          <span className="text-slate-600">—</span>
                        )}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* ── Conteúdo da Aba: Visão Geral e Selos Recentes ───────────────────── */}
      {abaAtual === "metricas" && (
        <div className="space-y-6">
          <div className="rounded-3xl border border-slate-800 bg-slate-900/60 p-6">
            <h3 className="text-base font-bold text-white mb-2">
              Últimos Selos de Horas Registrados
            </h3>
            <p className="text-xs text-slate-400 mb-4">
              Cada selo representa horas jogadas em reservas avulsas concluídas e pagas.
            </p>

            <div className="overflow-x-auto rounded-2xl border border-slate-800">
              <table className="w-full text-left text-xs text-slate-300">
                <thead className="bg-slate-950 text-slate-400 font-bold uppercase text-[10px] tracking-wider border-b border-slate-800">
                  <tr>
                    <th className="py-3 px-4">Reserva ID</th>
                    <th className="py-3 px-4">Usuário</th>
                    <th className="py-3 px-4">Horas</th>
                    <th className="py-3 px-4">Valor / Hora</th>
                    <th className="py-3 px-4">Data do Jogo</th>
                    <th className="py-3 px-4">Expiração do Selo</th>
                    <th className="py-3 px-4">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-800/60">
                  {todosSelos.length === 0 ? (
                    <tr>
                      <td colSpan={7} className="py-8 text-center text-slate-500">
                        Nenhum selo registrado ainda. Os selos são gerados automaticamente quando
                        reservas avulsas são concluídas.
                      </td>
                    </tr>
                  ) : (
                    todosSelos.slice(0, 15).map((selo) => (
                      <tr key={selo.id} className="hover:bg-slate-800/30 transition-colors">
                        <td className="py-3.5 px-4 font-mono text-emerald-400">
                          #{selo.reservaId.substring(0, 8)}
                        </td>
                        <td className="py-3.5 px-4 text-slate-300 truncate max-w-[120px]">
                          {selo.usuarioId}
                        </td>
                        <td className="py-3.5 px-4 font-bold text-white">
                          {selo.horasContabilizadas}h
                        </td>
                        <td className="py-3.5 px-4">{formatarMoeda(selo.valorPorHora)}</td>
                        <td className="py-3.5 px-4 text-slate-400">
                          {formatarDataExibicao(selo.dataJogo)}
                        </td>
                        <td className="py-3.5 px-4 text-slate-400">
                          {formatarDataExibicao(selo.expiraEm)}
                        </td>
                        <td className="py-3.5 px-4">
                          {selo.resgatado ? (
                            <span className="text-teal-400 font-semibold text-[10px]">
                              Resgatado em Voucher
                            </span>
                          ) : (
                            <span className="text-emerald-400 font-semibold text-[10px]">
                              Ativo na Cartela
                            </span>
                          )}
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

