/**
 * Injeta os dados dos 4 cenários de demonstração no armazenamento local
 * (usuários, reservas, selos e vouchers) para teste imediato no navegador.
 */
export function semearDadosDemonstracaoFidelidade(): void {
  if (typeof window === "undefined") return;

  try {
    // 1. Semear Usuários no reservei_users_db
    const rawUsers = localStorage.getItem("reservei_users_db");
    const currentUsers = rawUsers ? JSON.parse(rawUsers) : [];

    for (const demo of USUARIOS_DEMO_FIDELIDADE) {
      const digits = demo.usuario.telefone.replace(/\D/g, "");
      const existe = currentUsers.some(
        (u: { telefone: string; id: string }) =>
          u.telefone.replace(/\D/g, "") === digits || u.id === demo.usuario.id
      );

      if (!existe) {
        currentUsers.push({
          id: demo.usuario.id,
          nome: demo.usuario.nome,
          telefone: digits,
          senha: demo.usuario.senha,
          data_nascimento: demo.usuario.dataNascimento,
          criado_em: demo.usuario.criadoEm,
        });
      }
    }
    localStorage.setItem("reservei_users_db", JSON.stringify(currentUsers));

    // 2. Semear Selos no reservei_fidelidade_selos
    const rawSelos = localStorage.getItem("reservei_fidelidade_selos");
    const currentSelos: SeloFidelidade[] = rawSelos ? JSON.parse(rawSelos) : [];

    for (const demo of USUARIOS_DEMO_FIDELIDADE) {
      for (const selo of demo.selos) {
        if (!currentSelos.some((s) => s.id === selo.id)) {
          currentSelos.push(selo);
        }
      }
    }
    localStorage.setItem("reservei_fidelidade_selos", JSON.stringify(currentSelos));

    // 3. Semear Vouchers no reservei_fidelidade_vouchers
    const rawVouchers = localStorage.getItem("reservei_fidelidade_vouchers");
    const currentVouchers: VoucherFidelidade[] = rawVouchers ? JSON.parse(rawVouchers) : [];

    for (const demo of USUARIOS_DEMO_FIDELIDADE) {
      for (const vch of demo.vouchers) {
        if (!currentVouchers.some((v) => v.id === vch.id)) {
          currentVouchers.push(vch);
        }
      }
    }
    localStorage.setItem("reservei_fidelidade_vouchers", JSON.stringify(currentVouchers));

    // 4. Semear Reservas no reservei-v2
    const rawReservas = localStorage.getItem("reservei-v2");
    let storeState = rawReservas ? JSON.parse(rawReservas) : { state: { reservas: [] } };
    if (!storeState.state) storeState = { state: { reservas: [] } };

    const reservasAtuais: Reserva[] = storeState.state.reservas || [];

    for (const demo of USUARIOS_DEMO_FIDELIDADE) {
      for (const res of demo.reservas) {
        if (!reservasAtuais.some((r) => r.id === res.id)) {
          reservasAtuais.push(res);
        }
      }
    }
    storeState.state.reservas = reservasAtuais;
    localStorage.setItem("reservei-v2", JSON.stringify(storeState));
  } catch (err) {
    console.error("[seedFidelidade] Erro ao semear dados:", err);
  }
}

/**
 * Componente de Seletor de Contas de Demonstração do Sistema de Fidelidade.
 * Permite ao usuário alternar instantaneamente entre as 4 situações de fidelidade
 * com 1 clique (Lucas = vazio, Mateus = no meio, Rodrigo = premiado, Felipe = expirado).
 */

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import {
  Sparkles,
  Users,
  Award,
  Clock,
  History,
  ShieldCheck,
  ChevronRight,
  Loader2,
} from "lucide-react";
import {
  USUARIOS_DEMO_FIDELIDADE,
  semearDadosDemonstracaoFidelidade,
  type DemoUsuarioFidelidade,
} from "@/lib/fidelidade/seedFidelidade";
import { useUserAuth } from "@/hooks/useUserAuth";

export function PainelContasDemonstracao() {
  const router = useRouter();
  const { login } = useUserAuth();
  const [carregandoId, setCarregandoId] = useState<string | null>(null);

  const handleSelecionarConta = async (demo: DemoUsuarioFidelidade) => {
    setCarregandoId(demo.usuario.id);
    try {
      // 1. Garante que os dados de seed existam no LocalStorage
      semearDadosDemonstracaoFidelidade();

      // 2. Efetua o login direto
      const res = await login(demo.usuario.telefone, demo.usuario.senha);

      if (res.success) {
        toast.success(`Entrando como ${demo.usuario.nome}! 👋`, {
          description: demo.descricao,
        });
        router.push("/minha-conta");
      } else {
        toast.error("Erro ao alternar para conta de demonstração.");
      }
    } catch (err) {
      console.error("[PainelContasDemonstracao] Erro:", err);
      toast.error("Falha ao carregar conta de demonstração.");
    } finally {
      setCarregandoId(null);
    }
  };

  const getBadgeCenario = (cenario: DemoUsuarioFidelidade["cenario"]) => {
    switch (cenario) {
      case "vazio":
        return {
          label: "0 Horas (Vazio)",
          bg: "bg-slate-800 text-slate-300 border-slate-700",
          icon: Users,
        };
      case "meio":
        return {
          label: "6 Horas (No Meio)",
          bg: "bg-teal-500/10 text-teal-300 border-teal-500/20",
          icon: Clock,
        };
      case "cheio":
        return {
          label: "12 Horas (Voucher Ativo)",
          bg: "bg-emerald-500/15 text-emerald-300 border-emerald-500/30",
          icon: Award,
        };
      case "expirado":
        return {
          label: "Expirado / Histórico",
          bg: "bg-amber-500/10 text-amber-300 border-amber-500/20",
          icon: History,
        };
    }
  };

  return (
    <div className="rounded-3xl bg-slate-900/90 border border-slate-800 p-5 sm:p-6 shadow-xl space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2.5">
          <div className="w-8 h-8 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center">
            <Sparkles className="w-4 h-4 text-emerald-400" />
          </div>
          <div>
            <h3 className="text-sm font-bold text-white tracking-tight">
              Testar Perfis de Demonstração
            </h3>
            <p className="text-[11px] text-slate-400">
              Clique em qualquer perfil abaixo para alternar sem precisar digitar dados:
            </p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        {USUARIOS_DEMO_FIDELIDADE.map((demo) => {
          const badge = getBadgeCenario(demo.cenario);
          const Icon = badge.icon;
          const estaCarregando = carregandoId === demo.usuario.id;

          return (
            <button
              key={demo.usuario.id}
              onClick={() => handleSelecionarConta(demo)}
              disabled={Boolean(carregandoId)}
              className="text-left p-3.5 rounded-2xl bg-slate-950/70 hover:bg-slate-950 border border-slate-800/80 hover:border-emerald-500/40 transition-all duration-200 group flex flex-col justify-between"
            >
              <div>
                <div className="flex items-center justify-between gap-2 mb-2">
                  <span
                    className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-lg text-[10px] font-bold border ${badge.bg}`}
                  >
                    <Icon className="w-3 h-3" />
                    {badge.label}
                  </span>
                  <span className="text-[10px] text-slate-500 font-mono">
                    Senha: {demo.usuario.senha}
                  </span>
                </div>

                <p className="text-sm font-bold text-white group-hover:text-emerald-300 transition-colors">
                  {demo.usuario.nome}
                </p>
                <p className="text-[11px] text-slate-400 mt-0.5 leading-snug">
                  {demo.descricao}
                </p>
              </div>

              <div className="mt-3 pt-2.5 border-t border-slate-800/60 flex items-center justify-between text-[11px] text-emerald-400 font-semibold">
                <span className="text-slate-500 font-mono">{demo.usuario.telefone}</span>
                <span className="flex items-center gap-1">
                  {estaCarregando ? (
                    <Loader2 className="w-3 h-3 animate-spin" />
                  ) : (
                    <>
                      Entrar
                      <ChevronRight className="w-3 h-3 transition-transform group-hover:translate-x-0.5" />
                    </>
                  )}
                </span>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
}

