etry.error;\\r\\n187:       } else {\\r\\n188:         return true;\\r\\n189:       }\\r\\n190:     }\\r\\n191: \\r\\n192:     if (error) {\\r\\n193:       console.error(`[Supabase] Erro ao atualizar reserva ${id}:`, error.message);\\r\\n194:       return false;\\r\\n195:     }\\r\\n196: \\r\\n197:     return true;\\r\\n198:   } catch (err) {\\r\\n199:     console.error(`[Supabase] Falha inesperada ao atualizar reserva ${id}:`, err);\\r\\n200:     return false;\\r\\n201:   }\\r\\n202: }\\r\\n203: \\r\\n204: /**\\r\\n205:  * Remove uma reserva do banco de dados Supabase.\\r\\n206:  */\\r\\n207: export async function removerReservaSupabase(id: string): Promise\u003cboolean\u003e {\\r\\n208:   if (!isSupabaseConfigured()) {\\r\\n209:     return false;\\r\\n210:   }\\r\\n211: \\r\\n212:   try {\\r\\n213:     const { error } = await supabase\\r\\n214:       .from(TABELA_RESERVAS)\\r\\n215:       .delete()\\r\\n216:       .eq(\\\"id\\\", id);\\r\\n217: \\r\\n218:     if (error) {\\r\\n219:       console.error(`[Supabase] Erro ao remover reserva ${id}:`, error.message);\\r\\n220:       return false;\\r\\n221:     }\\r\\n222: \\r\\n223:     return true;\\r\\n224:   } catch (err) {\\r\\n225:     console.error(`[Supabase] Falha inesperada ao remover reserva ${id}:`, err);\\r\\n226:     return false;\\r\\n227:   }\\r\\n228: }\\r\\n229: \\r\\n230: /**\\r\\n231:  * Cria uma inscrição Realtime para escutar inserções, atualizações e deleções\\r\\n232:  * na tabela 'reservas' em tempo real.\\r\\n233:  */\\r\\n234: export function subscreverReservasSupabase(\\r\\n235:   onInsert: (reserva: Reserva) =\u003e void,\\r\\n236:   onUpdate: (reserva: Reserva) =\u003e void,\\r\\n237:   onDelete: (id: string) =\u003e void\\r\\n238: ) {\\r\\n239:   if (!isSupabaseConfigured()) {\\r\\n240:     return () =\u003e {};\\r\\n241:   }\\r\\n242: \\r\\n243:   // Remove qualquer canal anterior com mesmo prefixo para evitar conflito de callbacks após subscribe\\r\\n244:   try {\\r\\n245:     const canaisExistentes = supabase.getChannels();\\r\\n246:     for (const c of canaisExistentes) {\\r\\n247:       if (c.topic.includes(\\\"mudancas-reservas-realtime\\\")) {\\r\\n248:         void supabase.removeChannel(c);\\r\\n249:       }\\r\\n250:     }\\r\\n251:   } catch (err) {\\r\\n252:     console.warn(\\\"[Supabase] Aviso ao limpar canais anteriores:\\\", err);\\r\\n253:   }\\r\\n254: \\r\\n255:   const canalId = `mudancas-reservas-realtime-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;\\r\\n256:   const canal = supabase\\r\\n257:     .channel(canalId)\\r\\n258:     .on(\\r\\n259:       \\\"postgres_changes\\\",\\r\\n260:       {\\r\\n261:         event: \\\"INSERT\\\",\\r\\n262:         schema: \\\"public\\\",\\r\\n263:         table: TABELA_RESERVAS,\\r\\n264:       },\\r\\n265:       (payload) =\u003e {\\r\\n266:         const nova = rowToReserva(payload.new as ReservaDbRow);\\r\\n267:         onInsert(nova);\\r\\n268:       }\\r\\n269:     )\\r\\n270:     .on(\\r\\n271:       \\\"postgres_changes\\\",\\r\\n272:       {\\r\\n273:         event: \\\"UPDATE\\\",\\r\\n274:         schema: \\\"public\\\",\\r\\n275:         table: TABELA_RESERVAS,\\r\\n276:       },\\r\\n277:       (payload) =\u003e {\\r\\n278:         const atualizada = rowToReserva(payload.new as ReservaDbRow);\\r\\n279:         onUpdate(atualizada);\\r\\n280:       }\\r\\n281:     )\\r\\n282:     .on(\\r\\n283:       \\\"postgres_changes\\\",\\r\\n284:       {\\r\\n285:         event: \\\"DELETE\\\",\\r\\n286:         schema: \\\"public\\\",\\r\\n287:         table: TABELA_RESERVAS,\\r\\n288:       },\\r\\n289:       (payload) =\u003e {\\r\\n290:         const idDeletado = (payload.old as { id?: string })?.id;\\r\\n291:         if (idDeletado) {\\r\\n292:           onDelete(idDeletado);\\r\\n293:         }\\r\\n294:       }\\r\\n295:     )\\r\\n296:     .subscribe();\\r\\n297: \\r\\n298:   return () =\u003e {\\r\\n299:     void supabase.removeChannel(canal);\\r\\n300:   };\\r\\n301: }\\r