  const num = typeof valor === "number" ? valor : Number(valor);
  if (isNaN(num) || !isFinite(num)) {
    return (0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
  }
  return num.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

